              "(혀를 쯧 차고 울타리 쪽으로 돌아선다. 못 하나를 입에 문다)\n....마음대로 해. 네 신발이지 내 신발이냐.\n자빠지면 나한테 오지 마. 난 목수다. 의사 아니다.\n(쾅, 일부러 크게 못을 박는다)",
              "(못을 박으려다 손이 멈춘다. 한참 뒤에 등을 돌린 채 중얼거린다)\n....아니. 자빠지면 와.\n붕대는 있다. 공방 선반 두 번째 칸. 감는 건 내가 잘한다. 손이 커서 빠르다. 아프면 참지 말고."
