              "(쾅, 쾅. 못 박는 소리가 아까보다 훨씬 커진다. 울타리가 부르르 떤다)\n....가라.\n여기 있어 봐야 시끄럽기만 하다. 톱밥 먼지도 날리고. 너한테 좋을 거 없다.\n(곁눈질로 네 신발을 한 번 더 본다)",
