          "이 일지를 보여 드린 건 촌장님 다음으로 {name} 님이 처음입니다.\n(공책을 쥔 앞발이 살짝 떨린다)\n보여 드리기 전까지 몇 번이나 넣었다 꺼냈는지 모릅니다. 그래도 {name} 님이라면 괜찮을 것 같았습니다. 지금도 꼬리가 떨리고 있습니다.",
