          "(낡은 목걸이를 꺼낸다)\n아기 때 제 목에 걸려 있던 겁니다.\n끈은 해지고 색이 바랬지만, 오 년 동안 무기고 가장 깊은 서랍에 넣어 두고 밤마다 꺼내 봤습니다. 꺼내 볼 때마다 손이 떨려서 끈을 몇 번이나 다시 묶었습니다.",
