          "(마을 입구에서 멈춘다)\n여기가 제가 처음 발견된 곳입니다.\n표지판 아래, 바람이 덜 부는 이 자리요. 오 년 동안 매일 지켰지만, 오늘처럼 천천히 들여다본 건 처음입니다. 이 자리가 처음으로 무섭지 않습니다.",
