        "흥. 꽃 살 거 아니면 구경만 해.\n(물뿌리개를 든 채 고개만 까딱 돌린다)\n만지지 마. 가시 있어. 꽃한테도 있고, 나한테도 있어. 아침에 꽃 언덕에서 막 따 온 거라 다들 예민하거든. 찔려도 난 몰라.",
